import{_ as s,I as t,o as r,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"智能旅遊規劃 Agent 平臺開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"zh-tw/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"zh-tw/stage-2/assignments/travel-planning-agent-platform/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=e('<h1 id="智能旅遊規劃-agent-平臺開發實戰" tabindex="-1">智能旅遊規劃 Agent 平臺開發實戰 <a class="header-anchor" href="#智能旅遊規劃-agent-平臺開發實戰" aria-label="Permalink to “智能旅遊規劃 Agent 平臺開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD，從零完成一個智能旅遊規劃 Agent 平臺。你將構建一個能接收結構化輸入、生成每日行程、支持保存和重用的完整 AI 產品——不只是聊天機器人，而是一個有任務管理能力的產品。</p><p>這是 Stage 2 的綜合實戰環節。這個項目的核心挑戰在於：如何讓 AI 生成結構化、可用的行程規劃，而不是一大段不可操作的文字。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀 PRD 並從中提取 Agent 平臺的開發任務清單</li><li>設計結構化的輸入表單和結構化的輸出格式</li><li>實現 Agent 編排層，處理用戶輸入、模型調用和結果存儲</li><li>構建&quot;生成 → 保存 → 重用&quot;的業務閉環</li><li>完成端到端聯調，交付可演示的 AI 產品原型</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個智能旅遊規劃 Agent 平臺：</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td><strong>行程規劃</strong></td><td>用戶輸入出發地、目的地、日期、預算和偏好，系統生成每日行程</td></tr><tr><td><strong>預算拆分</strong></td><td>行程結果包含預算分配和建議</td></tr><tr><td><strong>歷史管理</strong></td><td>用戶可以保存歷史計劃、再次生成、導出</td></tr><tr><td><strong>管理後臺</strong></td><td>管理員查看熱門目的地、失敗任務和用戶反饋</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',14)),h("div",c,[i(n,null,{default:o(()=>[i(l,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，明確頁面、Agent 編排、輸入輸出結構"},{title:"搭建骨架",description:"用 AI 生成首頁、規劃頁、歷史頁、後臺頁骨架"},{title:"迭代開發",description:"逐模塊補充結構化輸出、任務狀態、歷史管理"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>第一版是否只做單目的地？</li><li>行程輸出是否必須結構化？結構是什麼？</li><li>導出能力做多深？（分享鏈接 / PDF / 圖片）</li><li>後臺統計和任務日誌的範圍是什麼？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;規劃頁&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Agent 編排層&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;模型調用&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;資料庫&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;歷史計劃&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;後臺統計與日誌&quot;]</span></span></code></pre></div><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成前端頁面" tabindex="-1">2.1 生成前端頁面 <a class="header-anchor" href="#_2-1-生成前端頁面" aria-label="Permalink to “2.1 生成前端頁面”">​</a></h3><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個智能旅遊規劃 Agent 平臺的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 頁面包括：首頁、規劃頁、行程詳情頁、歷史記錄頁、管理頁</span></span>
<span class="line"><span>2. 規劃頁左側是表單，右側是結果預覽</span></span>
<span class="line"><span>3. 先只生成頁面結構和假資料，不接真實接口</span></span>
<span class="line"><span>4. 風格要像現代 AI 產品</span></span></code></pre></div><h3 id="_2-2-驗證頁面結構" tabindex="-1">2.2 驗證頁面結構 <a class="header-anchor" href="#_2-2-驗證頁面結構" aria-label="Permalink to “2.2 驗證頁面結構”">​</a></h3><p>逐項檢查：</p><ul><li>[ ] 規劃頁的表單字段是否與 PRD 一致</li><li>[ ] 結果預覽區域能展示結構化的行程資料</li><li>[ ] 歷史記錄頁可以展示多條計劃</li><li>[ ] 管理後臺頁可以展示統計資料</li></ul><h2 id="第三部分-迭代開發" tabindex="-1">第三部分：迭代開發 <a class="header-anchor" href="#第三部分-迭代開發" aria-label="Permalink to “第三部分：迭代開發”">​</a></h2><h3 id="_3-1-按模塊推進" tabindex="-1">3.1 按模塊推進 <a class="header-anchor" href="#_3-1-按模塊推進" aria-label="Permalink to “3.1 按模塊推進”">​</a></h3><ol><li><strong>鑑權</strong>：註冊、登錄</li><li><strong>規劃表單</strong>：結構化輸入（出發地、目的地、日期、預算、偏好）</li><li><strong>Agent 編排</strong>：接收輸入 → 調用模型 → 解析結構化輸出</li><li><strong>結果展示</strong>：行程按天展示、預算拆分、建議</li><li><strong>歷史管理</strong>：保存計劃、再次生成、導出</li><li><strong>管理後臺</strong>：熱門目的地、失敗任務、用戶反饋</li><li><strong>任務狀態</strong>：生成中 / 成功 / 失敗的狀態管理和錯誤記錄</li></ol><h3 id="_3-2-模塊自檢" tabindex="-1">3.2 模塊自檢 <a class="header-anchor" href="#_3-2-模塊自檢" aria-label="Permalink to “3.2 模塊自檢”">​</a></h3><table tabindex="0"><thead><tr><th>檢查項</th><th>驗證方法</th></tr></thead><tbody><tr><td>輸入完整性</td><td>表單字段是否與 PRD 一致</td></tr><tr><td>輸出結構化</td><td>行程結果是不是結構化資料（而非一大段文字）</td></tr><tr><td>資料一致性</td><td>trip、itinerary、logs 資料是否對得上</td></tr><tr><td>閉環驗證</td><td>是否能演示&quot;輸入 → 生成 → 保存 → 再次生成&quot;</td></tr></tbody></table><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>至少驗證以下場景：</p><ul><li>輸入行程參數 → 生成每日行程 → 查看預算拆分 → 保存到歷史</li><li>從歷史記錄中再次生成行程</li><li>管理員查看任務統計和失敗日誌</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（規劃頁、行程詳情頁、歷史記錄頁、管理後臺）</li><li>[ ] 60 秒演示影片</li></ul><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>PRD 對齊</td><td>頁面、功能、資料結構基本符合 PRD</td><td>能清晰說明設計決策</td></tr><tr><td>產品閉環</td><td>規劃 → 保存 → 歷史 → 重生成可跑通</td><td>支持導出和分享</td></tr><tr><td>輸出質量</td><td>行程結果結構化且可讀</td><td>預算拆分合理、建議有針對性</td></tr><tr><td>後臺能力</td><td>任務統計和失敗日誌可查看</td><td>有熱門目的地分析</td></tr><tr><td>工程完整度</td><td>前端、後端、資料庫、模型調用鏈路已接通</td><td>任務狀態管理完善，錯誤可追溯</td></tr></tbody></table><h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li></ul>`,30))])}const x=s(p,[["render",b]]);export{P as __pageData,x as default};
